Let $\nu_t^{(1:N)}$ denote the offspring numbers in an interacting particle system satisfying \textup{standing_assumption} and such that, for any sufficiently large $N$ and for all $t \in [ 0, \infty )$, $\mathbb{P}[ \tau_N(t) = \infty ] =0$. Suppose that there exists a deterministic sequence $(b_N)_{N\in\mathbb{N}}$ such that ${\lim}_{N\to\infty} b_N =0$ and, for all large enough $N$,
\begin{equation}
\frac{1}{(N)_3} \sum_{i = 1}^N \mathbb{E}\left[ (\nu_t^{(i)})_3 \,\middle|\, \mathcal{F}_{t - 1} \right]  \leq b_N \frac{1}{(N)_2} \sum_{i = 1}^N \mathbb{E}\left[ (\nu_t^{(i)})_2 \,\middle|\, \mathcal{F}_{t - 1} \right],
\end{equation}
almost surely, uniformly in $t \geq 1$.
Then the rescaled genealogical process $(G_{\tau_N(t)}^{(n,N)})_{t\geq0}$ converges weakly in $\mathcal{D}$ to Kingman's $n$-coalescent as $N \to \infty$.

Assume (5) holds.
Fix $k \in \mathbb{N}$, $i_0:=0$, $i_k:=k$. For any sequence of times
$0 = t_0 \leq t_1 \leq \cdots \leq t_k \leq t$,
\begin{align*}
\lim_{N\to\infty} \mathbb{E} \Bigg[ 
        \sum_{\substack{r_1 <\dots< r_k :\\ r_i \leq \tau_N(t_i) \forall i}}
        &\Bigg( \prod_{i=1}^k p_{r_i} \Bigg)
        \Bigg( \prod_{\substack{r=1 \\ \notin \{r_1,\dots,r_k\} }}^{\tau_N(t)} 
        (1-p_r) \Bigg) \Bigg] \\
&\geq \alpha_n^k e^{-\alpha_n t}
        \sum_{\substack{i_1\leq \dots\leq i_{k-1}\\ \in \{0,\dots,k\} :
        i_j \geq j}}
        \prod_{j=1}^k \frac{(t_j - t_{j-1})^{i_j - i_{j-1}}}{(i_j - i_{j-1})! } .
\end{align*}

Assume (5) holds.
Fix $k \in \mathbb{N}$, $i_0:=0$, $i_k:=k$. For any sequence of times
$0 = t_0 \leq t_1 \leq \cdots \leq t_k \leq t$,
\begin{align*}
\lim_{N\to\infty} \mathbb{E} \Bigg[ 
        \sum_{\substack{r_1 <\dots< r_k :\\ r_i \leq \tau_N(t_i) \forall i}}
        &\Bigg( \prod_{i=1}^k p_{r_i} \Bigg)
        \Bigg( \prod_{\substack{r=1 \\ \notin \{r_1,\dots,r_k\} }}^{\tau_N(t)} 
        (1-p_r) \Bigg) \Bigg] \\
&\leq \alpha_n^k e^{-\alpha_n t}
        \sum_{\substack{i_1\leq \dots\leq i_{k-1}\\ \in \{0,\dots,k\} :
         i_j \geq j}} 
        \prod_{j=1}^k \frac{(t_j - t_{j-1})^{i_j - i_{j-1}}}{(i_j - i_{j-1})! } .
\end{align*}

Fix $t>0$, and recall that $(\mathcal{F}_r)$ is the backwards-in-time filtration generated by the offspring counts $\nu_r^{(1:N)}$ at each generation $r$.
Let 
\begin{equation*}
    f_N : \Bigg\{ \nu^{(1:N)} : \nu^{(i)} \geq 0 \text{ for each } i \in [N], \text{ and } \sum_{ i = 1 }^N \nu^{(i)} = N \Bigg\} \mapsto \mathbb{R}.
\end{equation*}
Then 
\begin{equation*}
\mathbb{E} \Bigg[ \sum_{r=1}^{\tau_N(t)} f_N(\nu_r^{(1:N)}) \Bigg] 
= \mathbb{E} \Bigg[ \sum_{r=1}^{\tau_N(t)} \mathbb{E} [ f_N(\nu_r^{(1:N)}) \mid \mathcal{F}_{r-1} ] \Bigg] .
\end{equation*}

Let $\xi \in \mathcal{P}_n$, $N>2$. Then
\begin{equation*}
p_{\xi\xi}(t)
\geq 1 - \binom{|\xi|}{2} \frac{N^{|\xi|-2}}{(N-2)_{|\xi|-2}} \left[ c_N(t) + B_{|\xi|} D_N(t) \right],
\end{equation*}
where 
\begin{equation*}
B_{|\xi|} = K (|\xi|-1)! (|\xi|-2) \exp\big( 2 \sqrt{2(|\xi|-2)} \big)
\end{equation*}
for some $K>0$ that does not depend on $|\xi|$ or $N$.

Let $\xi \in \mathcal{P}_n$ and $B_{|\xi|}^\prime := \binom{|\xi|-1}{2}$. Then, for large enough $N$,
\begin{equation*}
p_{\xi\xi}(t)
\leq 1 - 1_N \binom{|\xi|}{2}
        \left[ c_N(t) - B_{|\xi|}^\prime D_N(t) \right].
\end{equation*}

For any fixed $t>0$, for $N$ sufficiently large,
\begin{equation*}
\mathbb{E} \Bigg[ \sum_{l=0}^\infty \Big| (-\alpha_n)^l 1_N \frac{1}{l!} t^l 
        \sum_{\substack{r_1 < \cdots < r_k : \\ r_i \leq \tau_N(t_i) \forall i}}
        \prod_{i=1}^k c_N(r_i) \Big| \Bigg]
< \infty .
\end{equation*}

Assume (5) holds.
Fix $k \in \mathbb{N}$, $i_0:=0$, $i_k:=k$. 
Let $E_N$ be a sequence of events such that 
$\lim_{N\to\infty} \mathbb{P}[E_N] =1$. 
Then for any sequence of times 
$0 = t_0 \leq t_1 \leq \cdots \leq t_k \leq t$,
\begin{equation*}
\lim_{N\to\infty} \mathbb{E} \Bigg[ \mathbbm{1}_{E_N} 
        \sum_{\substack{r_1<\dots<r_k :\\ r_i\leq \tau_N(t_i) \forall i}}
        \prod_{i=1}^k c_N(r_i) \Bigg] 
= \sum_{\substack{i_1\leq \dots\leq i_{k-1}\\ \in \{0,\dots,k\} :
        i_j \geq j}}
        \prod_{j=1}^k \frac{(t_j - t_{j-1})^{i_j - i_{j-1}}}{(i_j - i_{j-1})! } .
\end{equation*}

Fix $t>0$, $l\in\mathbb{N}$.
Then, for any constant $B>0$,
\begin{align*}
\sum_{\substack{ s_1, \dots, s_l =1 \\ \text{\normalfont{all distinct}} }}^{\tau_N(t)} &
        \prod_{j=1}^l \left[ c_N(s_j) + B D_N(s_j) \right] \\
&\leq \sum_{\substack{ s_1, \dots, s_l =1 \\ \text{\normalfont{all distinct}} }}^{\tau_N(t)} 
        \prod_{j=1}^l c_N(s_j)
        + \Bigg( \sum_{s=1}^{\tau_N(t)} D_N(s) \Bigg) (t+1)^{l-1} (1+B)^l .
\end{align*}

Fix $t>0$, $l\in\mathbb{N}$.
Then, for any constant $B>0$,
\begin{align*}
&\sum_{\substack{ s_1, \dots, s_l =1 \\ \text{\normalfont{all distinct}} }}^{\tau_N(t)} 
        \prod_{j=1}^l \left[ c_N(s_j) - B D_N(s_j) \right] \\
&\geq \sum_{\substack{ s_1, \dots, s_l =1 \\ \text{\normalfont{all distinct}} }}^{\tau_N(t)} 
        \prod_{j=1}^l c_N(s_j)
        - \left( \sum_{s=1}^{\tau_N(t)} D_N(s) \right) (t+1)^{l-1} (1+B)^l .
\end{align*}

{[brown2021thesis]}
Let $(A_N) , (B_N)$ be sequences of events. 
If $\lim_{N\to\infty}\mathbb{P}[A_N] = \lim_{N\to\infty}\mathbb{P}[B_N]=1$ then $\lim_{N\to\infty} \mathbb{P} [A_N \cap B_N] =1$.

Assume (16) holds.
Fix $t>0$.
Let $K$ be a constant not depending on $N$ or $r$.
Then
\begin{equation*}
\lim_{N\to\infty} \mathbb{P} \Bigg[ \bigcap_{r=1}^{\tau_N(t)} 
        \left\{ c_N(r) \geq K D_N(r) \right\} \Bigg] 
= 1 . 
\end{equation*}

Assume (15) holds.
Fix $k\in\mathbb{N}$, a sequence of times $0 = t_0 \leq t_1 \leq \cdots \leq t_k \leq t$, and let $K_{ 1 : k }$ be strictly positive constants.
Define the event
\begin{equation*}
E_N := \bigcap_{j=1}^k \Bigg\{ \sum_{s=\tau_N(t_{j-1})+1}^{\tau_N(t_j)}
        c_N(s)^2 \leq K_j \Bigg\} .
\end{equation*}
Then $\lim_{N\to\infty} \mathbb{P}[E_N] =1$.
